<div class="card"><h1>Create Auction Listing</h1><?php if($message): ?><div class="alert"><?= $message ?></div><?php endif; ?><form method="post" enctype="multipart/form-data"><label>Title</label><input name="title" required><label>Description</label><textarea name="description" required></textarea><label>Category</label><select name="category_id"><?php foreach($cats as $c): ?><option value="<?= $c['id'] ?>"><?= e($c['name']) ?></option><?php endforeach; ?></select><label>Condition</label><select name="condition"><option value="new">New</option><option value="like_new">Like New</option><option value="good">Good</option><option value="fair">Fair</option></select><label>Starting Price</label><input type="number" step="0.01" name="starting_price" required><label>Reserve Price</label><input type="number" step="0.01" name="reserve_price"><label>End Date/Time</label><input type="datetime-local" name="end_datetime" required><label>Images up to 5</label><input type="file" name="images[]" multiple accept="image/*"><button>Create Listing</button></form></div>
